INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (202, 1, 'kustomize 렌더와 적용', '`kustomization.yaml` 이 있는 폴더 `base` 에서 `kubectl kustomize base`, `kubectl apply -k base`, `kubectl apply -f base` 는 각각 무엇을 할까요?', '`-k` 는 폴더의 kustomization 을 읽어요.', NULL, NULL, '[]', 'choice', '["`kubectl kustomize base` 는 변환 결과를 클러스터에 바로 적용한다", "`apply -f base` 도 `kustomization.yaml` 을 읽어 변환해서 적용한다", "`kubectl kustomize base` 는 변환한 YAML 을 화면에 출력만 하고 클러스터는 바꾸지 않는다. `apply -k base` 는 변환 결과를 클러스터에 적용한다. `apply -f base` 는 폴더의 YAML 을 그대로 올려 `kustomization.yaml` 은 `apiVersion not set, kind not set` 검증 오류가 나고 생성기 같은 변환은 적용되지 않는다", "`apply -k base` 는 `kustomization.yaml` 이 없어도 폴더의 모든 YAML 을 적용한다"]', 2, '적용 전에 `kubectl kustomize` 로 결과를 눈으로 확인하는 습관이 안전합니다.', NULL, NULL, NULL, NULL),
  (202, 2, 'kustomization 파일이 없을 때', '`kustomization.yaml` 이 없는 빈 폴더에 `kubectl kustomize dir` 나 `kubectl apply -k dir` 를 하면 어떻게 될까요?', '찾는 파일 이름이 오류에 나와요.', NULL, NULL, '[]', 'choice', '["폴더의 YAML 을 알아서 찾아 적용한다", "`unable to find one of ''kustomization.yaml'', ''kustomization.yml'' or ''Kustomization'' in directory` 오류가 난다. 파일 이름은 이 세 가지 중 하나여야 한다", "빈 결과를 출력하고 성공으로 끝난다", "파일 이름은 `kustomize.yaml` 이어야 한다"]', 1, '파일 이름을 다르게 쓰면 `-k` 가 폴더를 인식하지 못합니다.', NULL, NULL, NULL, NULL),
  (202, 3, 'namePrefix, nameSuffix, namespace', '`resources: [../base]` 와 `namePrefix: dev-`, `nameSuffix: -v1`, `namespace: team-b` 를 가진 overlay 를 렌더하면 `web` Deployment, Service, 그리고 Deployment 가 참조하는 ConfigMap 은 어떻게 바뀔까요?', '이름이 바뀌면 참조도 따라가요.', NULL, NULL, '[]', 'choice', '["모든 리소스 이름이 `dev-web-v1` 처럼 접두사와 접미사가 붙고 `namespace` 가 `team-b` 로 채워진다. Deployment 안의 ConfigMap 참조도 바뀐 이름으로 자동으로 고쳐진다", "Deployment 의 ConfigMap 참조는 옛 이름 그대로 남는다", "`namePrefix` 는 Deployment 에만 적용된다", "`namespace` 는 `kubectl apply -n` 이 없으면 무시된다"]', 0, '같은 base 로 환경마다 이름과 네임스페이스만 다르게 배포할 때 씁니다.', NULL, NULL, NULL, NULL),
  (202, 4, 'labels 와 includeSelectors', 'kustomization 의 `labels` 에 `pairs` 로 `team: x` 를 주면 라벨은 어디에 붙을까요? `includeSelectors: true` 를 더하면요?', '셀렉터는 건드리면 위험해요.', NULL, NULL, '[]', 'choice', '["기본으로 `selector` 와 Pod 템플릿에도 붙는다", "`includeSelectors: true` 는 Pod 라벨을 지운다", "라벨은 Deployment 에만 붙는다", "기본은 각 리소스의 `metadata.labels` 에만 붙고 Deployment 의 `selector` 나 Pod 템플릿, Service 의 `selector` 에는 들어가지 않는다. `includeSelectors: true` 를 주면 `selector` 와 Pod 템플릿 라벨에도 추가된다"]', 3, '배포된 Deployment 의 `selector` 는 바꿀 수 없어서 `includeSelectors` 는 처음부터 정하는 편이 안전합니다.', NULL, NULL, NULL, NULL),
  (202, 5, 'images 로 이미지 바꾸기', 'base 의 Deployment 에 `image: nginx:1.27-alpine` 이 있습니다. overlay 의 `images: [{name: nginx, newTag: 1.26-alpine}]` 와 `newName: busybox`, `newTag: "1.36"` 를 쓰면 렌더 결과의 이미지는 각각 무엇일까요?', '원본 YAML 은 그대로 두고 바꿔요.', NULL, NULL, '[]', 'choice', '["`newTag` 를 쓰면 이미지 이름까지 `1.26-alpine` 으로 바뀐다", "`images` 는 base 의 YAML 파일을 직접 고친다", "`newTag` 만 쓰면 `nginx:1.26-alpine`, `newName` 과 `newTag` 를 함께 쓰면 `busybox:1.36` 이 된다. base 의 YAML 파일은 수정하지 않는다", "`name` 은 컨테이너 이름을 가리킨다"]', 2, '`name` 은 컨테이너가 아니라 원래 이미지 이름입니다.', NULL, NULL, NULL, NULL),
  (202, 6, 'replicas 와 patches', 'overlay 에서 `replicas: [{name: web, count: 3}]` 를 쓰면 무엇이 바뀔까요? `patches` 로 `replicas: 5` 가 든 부분 Deployment 파일을 지정하면요? JSON 패치(`op: replace`, `path: /spec/replicas`, `value: 7`)는요?', '패치는 이름이 같은 오브젝트에 합쳐져요.', NULL, NULL, '[]', 'choice', '["`patches` 는 새 Deployment 를 하나 더 만든다", "`replicas` 항목은 `web` 의 `spec.replicas` 를 3 으로 바꾼다. `patches` 의 `path` 에 부분 Deployment(이름 `web`, `replicas: 5`)를 주면 base 의 `web` 에 합쳐져 5 가 되고, JSON 패치는 `target` 으로 대상을 고른 뒤 `replace` 로 7 이 된다", "JSON 패치는 `target` 없이도 동작한다", "`replicas` 항목은 Pod 템플릿 라벨을 바꾼다"]', 1, '패치할 파일에는 이름과 종류(`kind`, `metadata.name`)가 있어야 대상을 찾습니다.', NULL, NULL, NULL, NULL),
  (202, 7, 'configMapGenerator 의 이름 해시', 'kustomization 의 `configMapGenerator`(`name: cfg`, `literals: [MODE=a]`)로 만든 ConfigMap 의 이름은 어떻게 될까요? 이를 `envFrom` 으로 참조하는 Deployment 는요?', '내용에 따라 이름 뒤에 붙는 값이 달라져요.', NULL, NULL, '[]', 'choice', '["`cfg-kdkkf5f9gt` 처럼 내용의 해시가 이름 뒤에 붙고, 같은 kustomization 에서 이 ConfigMap 을 참조하는 Deployment 의 이름도 자동으로 해시가 붙은 이름으로 고쳐진다. 내용이 같으면 해시도 같다", "이름은 항상 `cfg` 그대로이고 참조도 `cfg` 이다", "참조하는 Deployment 는 직접 해시를 적어 줘야 한다", "해시는 적용할 때마다 무작위로 바뀐다"]', 0, '`generatorOptions` 의 `disableNameSuffixHash: true` 를 주면 해시 없이 `cfg` 라는 이름이 됩니다.', NULL, NULL, NULL, NULL),
  (202, 8, '생성기 내용을 바꾸고 다시 apply', '`MODE=a` 로 `apply -k` 한 뒤 `MODE=z` 로 바꾸고 다시 `apply -k` 하면 ConfigMap 과 Deployment 는 어떻게 될까요?', '이름이 바뀌면 새 오브젝트예요.', NULL, NULL, '[]', 'choice', '["같은 이름의 ConfigMap 이 제자리에서 수정된다", "옛 ConfigMap 이 자동으로 삭제된다", "Deployment 는 바뀌지 않아 Pod 가 그대로 유지된다", "해시가 바뀐 새 ConfigMap 이 만들어지고 Deployment 의 참조가 새 이름으로 바뀌어 Pod 가 새로 롤링된다. 옛 해시의 ConfigMap 은 자동으로 지워지지 않고 남는다"]', 3, '남은 옛 ConfigMap 은 `kubectl delete cm <이름>` 으로 직접 정리합니다.', NULL, NULL, NULL, NULL),
  (202, 9, 'kubectl diff -k', '`kubectl diff -k dir` 은 변경이 없을 때와 있을 때 종료 코드가 얼마일까요? 클러스터를 바꾸기도 할까요?', '적용하지 않고 비교만 해요.', NULL, NULL, '[]', 'choice', '["차이가 있으면 변경을 적용한 뒤 0 을 돌려 준다", "차이가 있으면 0, 없으면 1 이다", "변경이 없으면 0, 차이가 있으면 1 이다. 클러스터는 바꾸지 않고 적용했을 때 달라질 부분만 보여 준다", "`diff` 는 `-k` 와 함께 쓸 수 없다"]', 2, 'CI 에서 배포 전 변경 여부를 확인할 때 씁니다.', NULL, NULL, NULL, NULL),
  (202, 10, 'kubectl delete -k', '`kubectl apply -k base` 로 만든 Deployment, Service, ConfigMap 을 `kubectl delete -k base` 로 지우면 어떻게 될까요? 그 사이에 생성기 내용을 바꿨다면요?', '지울 때도 현재 파일을 렌더해요.', NULL, NULL, '[]', 'choice', '["적용했던 시점의 오브젝트를 자동으로 기억해서 모두 지운다", "현재 렌더 결과에 있는 오브젝트를 모두 지운다(Deployment 와 Service 는 삭제됨). 생성기 내용을 바꿔 해시가 달라졌다면 렌더된 ConfigMap 이름이 클러스터에 없어 `NotFound` 오류가 나고 옛 해시의 ConfigMap 은 남는다", "ConfigMap 은 `delete -k` 로 지워지지 않는다", "생성기 내용을 바꿔도 항상 모두 지워진다"]', 1, '파일을 바꾸기 전에 지우거나 남은 ConfigMap 을 이름으로 직접 지웁니다.', NULL, NULL, NULL, NULL),
  (202, 11, 'kubectl run --rm', '`kubectl run r1 --image=busybox:1.36 --restart=Never --rm -i -- echo hello` 를 하면 어떻게 될까요? `--rm` 없이 `kubectl run r2 ... -- echo hello` 한 뒤에는요?', '`--rm` 은 끝난 뒤 정리해요.', NULL, NULL, '[]', 'choice', '["`r1` 은 `hello` 를 출력하고 끝나면 Pod 가 삭제되어(`pod \\"r1\\" deleted`) `kubectl get pod r1` 에 나오지 않는다. `--rm` 없이 실행한 `r2` 는 `Completed` 상태로 남고 `kubectl logs r2` 로 `hello` 를 볼 수 있다", "`--rm` 을 써도 Pod 는 남는다", "`--rm` 없이도 끝나면 Pod 가 자동으로 삭제된다", "`r2` 는 `Completed` 가 되면 로그도 사라진다"]', 0, '일회성 점검용 Pod 를 정리를 신경 쓰지 않고 띄울 때 편합니다.', NULL, NULL, NULL, NULL),
  (202, 12, '--rm 의 조건과 종료 코드', '`kubectl run r3 --image=busybox:1.36 --restart=Never --rm -- echo x` 는 어떻게 될까요? `-i --rm` 으로 `sh -c ''echo out; exit 4''` 를 실행하면 `kubectl` 의 종료 코드는요?', '`--rm` 은 붙어서 기다릴 때만 쓸 수 있어요.', NULL, NULL, '[]', 'choice', '["`-i` 없이도 `--rm` 이 잘 동작한다", "컨테이너가 실패해도 `kubectl` 의 종료 코드는 0 이다", "`--rm` 은 `--restart=Always` 와 함께만 쓸 수 있다", "`-i` 없이 `--rm` 만 쓰면 `--rm should only be used for attached containers` 오류가 난다. `-i --rm` 으로 실행하면 컨테이너의 출력이 보이고 Pod 는 삭제되며 `kubectl` 은 컨테이너의 종료 코드 4 로 끝난다"]', 3, '터미널이 필요하면 `-it` 를 함께 씁니다.', NULL, NULL, NULL, NULL),
  (202, 13, 'minReadySeconds', 'Deployment 에 `minReadySeconds: 8` 을 주고 적용한 직후(약 3초 뒤)와 12초쯤 뒤에 `kubectl get deploy` 의 READY 와 AVAILABLE 은 어떻게 보일까요?', '준비된 뒤에도 일정 시간을 기다려요.', NULL, NULL, '[]', 'choice', '["적용 직후부터 AVAILABLE 이 1 이다", "`minReadySeconds` 는 컨테이너 시작을 늦춘다", "3초쯤 뒤에는 Pod 가 `Running` 이라 READY 는 `1/1` 이지만 AVAILABLE 은 0 이고, 12초쯤 뒤에는 AVAILABLE 이 1 이 된다. Pod 가 Ready 가 된 뒤 이 시간 동안 문제가 없어야 \\"사용 가능\\"으로 센다", "`minReadySeconds` 가 지나도 AVAILABLE 은 0 이다"]', 2, '롤링 업데이트에서 새 Pod 가 안정적인지 잠시 지켜본 뒤 다음 단계로 넘어가게 해 줍니다.', NULL, NULL, NULL, NULL),
  (202, 14, 'overlay 구조', '`base/` 에 Deployment 와 Service, `overlay/kustomization.yaml` 에 `resources: [../base]` 와 `namePrefix: dev-` 가 있습니다. `kubectl apply -k overlay` 를 하면 base 파일은 바뀔까요? 클러스터에는 무엇이 올라갈까요?', 'overlay 는 base 를 참조해서 덧입혀요.', NULL, NULL, '[]', 'choice', '["base 의 YAML 파일에 `dev-` 가 직접 적힌다", "base 의 YAML 파일은 수정되지 않는다. overlay 가 base 를 불러와 변환(`dev-` 접두사 등)한 결과가 클러스터에 올라간다. 환경마다 overlay 폴더를 따로 두는 방식이다", "overlay 에는 base 의 모든 YAML 을 복사해 두어야 한다", "`apply -k overlay` 는 base 만 올리고 overlay 는 무시한다"]', 1, '`kubectl kustomize overlay` 로 어떻게 합쳐지는지 미리 볼 수 있습니다.', NULL, NULL, NULL, NULL),
  (202, 15, 'kustomize 로 적용', '폴더의 `kustomization.yaml` 을 읽어 **변환한 결과를 적용하는** `kubectl apply` 옵션을 채우세요.', '"kustomize"의 머리글자예요.', NULL, NULL, '[]', 'fill', '["-k", "-f", "-R", "-p"]', NULL, '`-f` 는 폴더의 YAML 을 그대로 올립니다.', '[0]', 'kubectl apply {0} ./overlay', NULL, NULL),
  (202, 16, '변환 결과만 출력', '클러스터는 바꾸지 않고 폴더의 **변환 결과 YAML 만 출력하는** `kubectl` 하위 명령을 채우세요.', '도구 이름과 같은 단어예요.', NULL, NULL, '[]', 'fill', '["kustomize", "render", "template", "build"]', NULL, '출력을 확인한 뒤 `apply -k` 로 적용합니다.', '[0]', 'kubectl {0} ./overlay', NULL, NULL),
  (202, 17, '리소스 목록 키', '`kustomization.yaml` 에서 **불러올 YAML 파일이나 base 폴더를 나열하는** 키를 채우세요.', '"자원"이라는 뜻의 복수형 영어 단어예요.', NULL, NULL, '[]', 'fill', '["resources", "include", "files", "imports"]', NULL, 'overlay 에서는 `../base` 를 나열합니다.', '[0]', '{0}:', NULL, NULL),
  (202, 18, '이름 접두사', '모든 리소스 이름 **앞에 문자열을 붙이는** `kustomization.yaml` 키를 채우세요.', '"name"과 "prefix"를 붙여 써요.', NULL, NULL, '[]', 'fill', '["namePrefix", "prefixName", "nameHead", "namePre"]', NULL, '뒤에 붙이는 것은 `nameSuffix` 입니다.', '[0]', '{0}: dev-', NULL, NULL),
  (202, 19, '네임스페이스 지정', '모든 리소스의 **네임스페이스를 한 번에 정하는** `kustomization.yaml` 키를 채우세요.', '"이름 공간"을 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["namespace", "ns", "target", "project"]', NULL, '`-n` 옵션 없이도 이 네임스페이스에 만들어집니다.', '[0]', '{0}: team-b', NULL, NULL),
  (202, 20, '이미지 바꾸기', '이미지 이름과 태그를 **YAML 을 고치지 않고 바꾸는** `kustomization.yaml` 키를 채우세요.', '"이미지"의 복수형이에요.', NULL, NULL, '[]', 'fill', '["images", "containers", "tags", "imageTags"]', NULL, '`name`, `newName`, `newTag` 를 하위에 씁니다.', '[0]', '{0}:', NULL, NULL),
  (202, 21, 'ConfigMap 만들기', '리터럴이나 파일로 **ConfigMap 을 만들어 주고 이름에 해시를 붙이는** `kustomization.yaml` 키를 채우세요.', '"ConfigMap"과 "Generator"를 붙여 써요.', NULL, NULL, '[]', 'fill', '["configMapGenerator", "configMaps", "configGen", "generateConfig"]', NULL, '내용이 바뀌면 해시가 바뀌어 Pod 가 롤링됩니다.', '[0]', '{0}:', NULL, NULL),
  (202, 22, '패치 지정', 'base 리소스에 **부분 수정을 덧입히는** `kustomization.yaml` 키를 채우세요.', '"패치"의 복수형이에요.', NULL, NULL, '[]', 'fill', '["patches", "overrides", "changes", "edits"]', NULL, '`path` 로 파일을, `target` 과 `patch` 로 JSON 패치를 지정합니다.', '[0]', '{0}:', NULL, NULL),
  (202, 23, '끝나면 Pod 삭제', '`kubectl run` 으로 만든 Pod 를 **끝난 뒤 자동으로 삭제하게** 하는 옵션을 채우세요.', '리눅스 `rm` 과 같은 이름이에요.', NULL, NULL, '[]', 'fill', '["--rm", "--del", "--clean", "--once"]', NULL, '`-i` 없이는 쓸 수 없습니다.', '[0]', 'kubectl run r1 --image=busybox:1.36 --restart=Never -i {0} -- echo hi', NULL, NULL),
  (202, 24, '사용 가능 판정 시간', 'Pod 가 Ready 가 된 뒤 **사용 가능으로 세기까지 기다리는 시간(초)** 을 정하는 Deployment `spec` 필드를 채우세요.', '"min", "ready", "seconds"를 이어서 써요.', NULL, NULL, '[]', 'fill', '["minReadySeconds", "readyDelaySeconds", "initialDelaySeconds", "startDelaySeconds"]', NULL, '`initialDelaySeconds` 는 프로브 시작을 늦추는 값입니다.', '[0]', '{0}: 8', NULL, NULL),
  (202, 25, '적용 전 비교', '적용하지 않고 **현재 클러스터와 달라질 부분만 보여 주는** `kubectl` 하위 명령을 채우세요.', '리눅스의 차이 비교 명령과 같은 이름이에요.', NULL, NULL, '[]', 'fill', '["diff", "compare", "plan", "preview"]', NULL, '차이가 있으면 종료 코드 1 입니다.', '[0]', 'kubectl {0} -k ./overlay', NULL, NULL),
  (202, 26, 'kustomize 로 안전하게 적용하기', '`kustomization.yaml` 을 쓰고 적용 전에 확인한 뒤 적용하는 순서입니다. 순서에 맞게 놓아 보세요.', '작성 → 렌더 → 비교 → 적용 순서예요.', NULL, NULL, '[]', 'order', '["`kustomization.yaml` 에 `resources` 와 `configMapGenerator` 를 쓴다", "`kubectl kustomize dir` 로 변환 결과를 눈으로 확인한다", "`kubectl diff -k dir` 로 클러스터와 달라지는 부분을 확인한다", "`kubectl apply -k dir` 로 적용한다"]', NULL, '`apply -f dir` 는 `kustomization.yaml` 을 변환하지 않으니 `-k` 를 씁니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (202, 27, 'base 와 overlay 로 환경 나누기', 'base 위에 환경별 overlay 를 얹어 적용하는 순서입니다. 순서에 맞게 놓아 보세요.', 'base → overlay → 렌더 → 적용 순서예요.', NULL, NULL, '[]', 'order', '["`base/` 에 Deployment, Service, `kustomization.yaml` 을 만든다", "`overlay/kustomization.yaml` 에 `resources: [../base]` 와 `namePrefix: dev-` 를 쓴다", "`kubectl kustomize overlay` 로 이름에 `dev-` 가 붙었는지 확인한다", "`kubectl apply -k overlay` 로 적용한다"]', NULL, 'base 파일은 수정하지 않고 overlay 만 환경마다 바꿉니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (202, 28, '설정을 바꿔 롤링하기', '`configMapGenerator` 의 값을 바꿔 Pod 를 새 설정으로 롤링하는 순서입니다. 순서에 맞게 놓아 보세요.', '수정 → 이름 확인 → 적용 → 정리 순서예요.', NULL, NULL, '[]', 'order', '["`kustomization.yaml` 의 `MODE=a` 를 `MODE=z` 로 고친다", "`kubectl kustomize dir` 로 ConfigMap 이름의 해시가 바뀌었는지 확인한다", "`kubectl apply -k dir` 로 적용하고 `kubectl rollout status` 로 롤링을 확인한다", "남은 옛 해시의 ConfigMap 을 `kubectl delete cm <이름>` 으로 정리한다"]', NULL, '옛 ConfigMap 은 자동으로 지워지지 않습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (202, 29, '일회성 Pod 로 점검하기', '`kubectl run --rm` 으로 일회성 Pod 를 돌려 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '실행 → 출력 → 삭제 확인 → 종료 코드 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl run r1 --image=busybox:1.36 --restart=Never --rm -i -- echo hi` 로 실행한다", "컨테이너의 출력 `hi` 가 화면에 나오는지 확인한다", "`kubectl get pod r1` 에 `NotFound` 가 나와 Pod 가 삭제됐는지 확인한다", "`echo $?` 로 컨테이너의 종료 코드가 전달됐는지 확인한다"]', NULL, '`-i` 없이 `--rm` 을 쓰면 오류가 납니다.', '[0, 1, 2, 3]', NULL, NULL, NULL);
